/**
 * Built-in HTTP channel admission for control-plane session starts.
 *
 * `agent-sdk run --prod` reaches the authenticated CP start route, which
 * delivers `agentsdk.session` to the built-in `http` channel of every v2
 * agent. The wake is `send(message, { dryRun, asOf, modelConfig, instructions })`; the session id,
 * when the caller resumed an explicit `ses_…`, arrives through the hosted
 * execution (never through this payload), so authored code cannot pick
 * one. {@link HttpChannelDefinition.onAdmit} runs against the mailbox
 * key and the original message before that send is captured.
 *
 * `agentsdk.eval-case` reserves the session's send for one eval case: the
 * hosted execution runs the case body there instead of a single turn. The
 * case body writes every message, so it skips `onAdmit` and `onMessage`.
 */
import { skipped, turnStarted } from "./channel-dispatch.js";
import { attachHostedAdmissionAdapter } from "./hosted-admission-adapter.js";
import { AGENT_SDK_EVAL_CASE_EVENT_TYPE, AGENT_SDK_HTTP_CHANNEL_KIND, AGENT_SDK_SESSION_EVENT_TYPE, } from "./hosted-catch-protocol.js";
import { isRecord } from "./is-record.js";
import { InvalidModelConfigError, modelConfigForDryRun } from "./model-config.js";
const PAYLOAD_KEYS = new Set(["message", "dryRun", "asOf", "modelConfig", "instructions"]);
const EVAL_CASE_PAYLOAD_KEYS = new Set(["runId", "caseId"]);
const MAX_MESSAGE_CHARS = 64 * 1024;
const MAX_INSTRUCTIONS_CHARS = 256 * 1024;
const INSTRUCTIONS_REQUIRE_DRY_RUN = "invalid argument: instructions is only allowed when dryRun is true";
const MAX_EVAL_ID_CHARS = 512;
/** Symbol-keyed so authored channels cannot forge an eval-case send. */
const EVAL_CASE = Symbol("agentsdk.eval-case");
/** The eval case an `agentsdk.eval-case` admission reserved this send for. */
export function evalCaseOf(options) {
    return options[EVAL_CASE];
}
export function parseControlPlaneSessionPayload(payload) {
    if (!isRecord(payload)) {
        return { ok: false, error: "payload must be an object" };
    }
    if (Object.keys(payload).some((key) => !PAYLOAD_KEYS.has(key))) {
        return { ok: false, error: "payload carries an unsupported field" };
    }
    const message = typeof payload.message === "string" ? payload.message.trim() : "";
    if (message.length === 0 || message.length > MAX_MESSAGE_CHARS) {
        return { ok: false, error: "payload.message is required" };
    }
    if (payload.dryRun !== undefined && typeof payload.dryRun !== "boolean") {
        return { ok: false, error: "payload.dryRun must be a boolean" };
    }
    if (payload.asOf !== undefined &&
        (typeof payload.asOf !== "string" || payload.asOf.trim().length === 0)) {
        return { ok: false, error: "payload.asOf must be a non-empty string" };
    }
    let modelConfig;
    if (payload.modelConfig !== undefined) {
        try {
            modelConfig = modelConfigForDryRun(payload.modelConfig, payload.dryRun === true ? true : undefined);
        }
        catch (error) {
            if (!(error instanceof InvalidModelConfigError))
                throw error;
            return { ok: false, error: error.message };
        }
    }
    let instructions;
    if (payload.instructions !== undefined) {
        if (typeof payload.instructions !== "string") {
            return { ok: false, error: "payload.instructions must be a string" };
        }
        instructions = payload.instructions.trim();
        if (instructions.length === 0) {
            return { ok: false, error: "payload.instructions must be a non-empty string" };
        }
        if (instructions.length > MAX_INSTRUCTIONS_CHARS) {
            return { ok: false, error: "payload.instructions is too long" };
        }
        if (payload.dryRun !== true) {
            return { ok: false, error: INSTRUCTIONS_REQUIRE_DRY_RUN };
        }
    }
    return {
        ok: true,
        data: {
            message,
            dryRun: payload.dryRun === true ? true : undefined,
            asOf: typeof payload.asOf === "string" ? payload.asOf.trim() : undefined,
            modelConfig,
            instructions,
        },
    };
}
export function parseControlPlaneEvalCasePayload(payload) {
    if (!isRecord(payload)) {
        return { ok: false, error: "payload must be an object" };
    }
    if (Object.keys(payload).some((key) => !EVAL_CASE_PAYLOAD_KEYS.has(key))) {
        return { ok: false, error: "payload carries an unsupported field" };
    }
    const runId = payload.runId;
    const caseId = payload.caseId;
    if (typeof runId !== "string" || runId.length === 0 || runId.length > MAX_EVAL_ID_CHARS) {
        return { ok: false, error: "payload.runId is required" };
    }
    if (typeof caseId !== "string" || caseId.length === 0 || caseId.length > MAX_EVAL_ID_CHARS) {
        return { ok: false, error: "payload.caseId is required" };
    }
    return { ok: true, data: { runId, caseId } };
}
async function dispatchEvalCase(payload, args) {
    const parsed = parseControlPlaneEvalCasePayload(payload);
    if (!parsed.ok) {
        return Response.json({ ok: false, error: parsed.error }, { status: 400 });
    }
    const options = {
        purpose: "eval",
        title: `Eval ${parsed.data.caseId}`,
        [EVAL_CASE]: parsed.data,
    };
    return turnStarted(await args.send(parsed.data.caseId, options));
}
export async function dispatchHttpControlPlaneSession(input) {
    if (input.eventType === AGENT_SDK_EVAL_CASE_EVENT_TYPE) {
        return dispatchEvalCase(input.payload, input.args);
    }
    if (input.eventType !== AGENT_SDK_SESSION_EVENT_TYPE) {
        return skipped("not a control-plane session");
    }
    const parsed = parseControlPlaneSessionPayload(input.payload);
    if (!parsed.ok) {
        return Response.json({ ok: false, error: parsed.error }, { status: 400 });
    }
    const original = parsed.data.message;
    if (input.onAdmit !== undefined) {
        await input.onAdmit({
            message: original,
            sessionKey: input.mailboxContinuationKey,
            dryRun: parsed.data.dryRun,
            asOf: parsed.data.asOf,
            modelConfig: parsed.data.modelConfig,
            instructions: parsed.data.instructions,
            host: input.args.host,
        });
    }
    const message = input.onMessage === undefined ? original : await input.onMessage(original, { auth: null });
    const session = await input.args.send(message, {
        dryRun: parsed.data.dryRun,
        asOf: parsed.data.asOf,
        modelConfig: parsed.data.modelConfig,
        instructions: parsed.data.instructions,
    });
    return turnStarted(session);
}
export function attachHttpControlPlaneAdmission(definition) {
    attachHostedAdmissionAdapter(definition, {
        kind: AGENT_SDK_HTTP_CHANNEL_KIND,
        dispatch: ({ eventType, payload, args, mailboxContinuationKey }) => dispatchHttpControlPlaneSession({
            eventType,
            payload,
            args,
            mailboxContinuationKey: mailboxContinuationKey ?? "",
            onMessage: definition.onMessage,
            onAdmit: definition.onAdmit,
        }),
    });
}
